public class LsmEngine {
    private final ConcurrentSkipListMap<byte[], byte[]> memTable = new ConcurrentSkipListMap<>(Bytes::compare);
    private final long maxMemTableSize = 64 * 1024 * 1024; // 64MB

    public void put(byte[] key, byte[] value) {
        // BUG: Synchronous flush on write thread when MemTable is full blocks write path
        if (memTable.size() >= maxMemTableSize) {
            flushToDiskSynchronous();
        }
        memTable.put(key, value);
    }
}

